/* Amber Minimal Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="amber-minimal-light"] {
  --background: #ffffff;
  --foreground: #262626;
  --card: #ffffff;
  --card-foreground: #262626;
  --popover: #ffffff;
  --popover-foreground: #262626;
  --primary: #f49f1e;
  --primary-foreground: #000000;
  --secondary: #f5f5f5;
  --secondary-foreground: #4b5666;
  --muted: #f8f8f8;
  --muted-foreground: #6c727e;
  --accent: #fffcf0;
  --accent-foreground: #8f4113;
  --destructive: #f14444;
  --destructive-foreground: #ffffff;
  --border: #e4e8ef;
  --input: #e4e8ef;
  --ring: #f49f1e;
  --chart-1: #f49f1e;
  --chart-2: #db7800;
  --chart-3: #b75301;
  --chart-4: #8f4113;
  --chart-5: #793207;
  --radius: 0.375rem;
  --sidebar: #f8f8f8;
  --sidebar-foreground: #262626;
  --sidebar-primary: #f49f1e;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #fffcf0;
  --sidebar-accent-foreground: #8f4113;
  --sidebar-border: #e4e8ef;
  --sidebar-ring: #f49f1e;
  --font-sans: Inter, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: JetBrains Mono, monospace;
  --shadow-color: #000000;
  --shadow-opacity: 0.1;
  --shadow-blur: 8px;
  --shadow-spread: -1px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 2px 4px -2px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 4px 6px -2px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 8px 10px -2px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 4px 8px -1px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="amber-minimal-dark"] {
  --background: #161616;
  --foreground: #e4e4e4;
  --card: #262626;
  --card-foreground: #e4e4e4;
  --popover: #262626;
  --popover-foreground: #e4e4e4;
  --primary: #f49f1e;
  --primary-foreground: #000000;
  --secondary: #262626;
  --secondary-foreground: #e4e4e4;
  --muted: #262626;
  --muted-foreground: #a4a4a4;
  --accent: #8f4113;
  --accent-foreground: #fde484;
  --destructive: #f14444;
  --destructive-foreground: #ffffff;
  --border: #404040;
  --input: #404040;
  --ring: #f49f1e;
  --chart-1: #fbc031;
  --chart-2: #db7800;
  --chart-3: #8f4113;
  --chart-4: #b75301;
  --chart-5: #8f4113;
  --radius: 0.375rem;
  --sidebar: #0f0f0f;
  --sidebar-foreground: #e4e4e4;
  --sidebar-primary: #f49f1e;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #8f4113;
  --sidebar-accent-foreground: #fde484;
  --sidebar-border: #404040;
  --sidebar-ring: #f49f1e;
  --font-sans: Inter, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: JetBrains Mono, monospace;
  --shadow-color: #000000;
  --shadow-opacity: 0.1;
  --shadow-blur: 8px;
  --shadow-spread: -1px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 2px 4px -2px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 4px 6px -2px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 8px 10px -2px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 4px 8px -1px hsl(0 0% 0% / 0.25);
}
